{
  "competitors": [
    {
      "name": "ServiceTitan",
      "slug": "servicetitan",
      "category": "direct",
      "description": "Enterprise-grade field service management platform serving HVAC, plumbing, electrical, and other trades. Backed by significant venture funding, targets mid-market and larger contractors. Known for comprehensive features including dispatch, invoicing, marketing, and financing integrations.",
      "key_differentiators": [
        "Deep feature set covering the full service-business lifecycle (scheduling, dispatch, invoicing, marketing)",
        "Strong integrations with financing, equipment, and accounting platforms",
        "Large market presence and brand recognition among established contractors"
      ],
      "why_included": "The enterprise-grade market leader in field service management; investors will ask about it first"
    },
    {
      "name": "Jobber",
      "slug": "jobber",
      "category": "direct",
      "description": "Cloud-based field service management software targeting SMBs across home services trades. Positions itself as easier to use than enterprise alternatives. Strong brand in the SMB field-service market, offering scheduling, invoicing, CRM, and client communications in one platform.",
      "key_differentiators": [
        "SMB-focused with a reputation for usability and fast onboarding",
        "Broad coverage across 50+ service industries",
        "Competitive pricing relative to enterprise tools"
      ],
      "why_included": "The most direct SMB-focused competitor to Tessivane; targets identical buyers with overlapping product scope"
    },
    {
      "name": "Housecall Pro",
      "slug": "housecall-pro",
      "category": "direct",
      "description": "Mobile-first field service management platform for home service businesses. Targets SMBs with an emphasis on ease of use, mobile dispatch, and consumer-facing features like online booking and payment. Backed by meaningful growth capital.",
      "key_differentiators": [
        "Mobile-first UX with strong technician-facing apps",
        "Consumer-facing features: online booking, automated review requests, payment processing",
        "Active community and franchise support"
      ],
      "why_included": "A well-funded SMB-focused direct competitor with overlapping buyer profile and product surface area"
    },
    {
      "name": "Manual scheduling (whiteboard, phone, spreadsheets)",
      "slug": "manual-scheduling",
      "category": "do_nothing",
      "description": "Many SMB service businesses manage scheduling and dispatch manually using whiteboards, phone calls, paper job tickets, and spreadsheets like Excel or Google Sheets. This is the status quo for a large segment of the market that has not yet adopted dedicated software.",
      "key_differentiators": [
        "Zero software cost and no vendor risk",
        "No onboarding or training required — the owner already knows how to use a spreadsheet",
        "Full flexibility — no workflow constraints imposed by a software product"
      ],
      "why_included": "For many SMB service businesses, the real competitor is inertia and the status quo, not another software product"
    }
  ],
  "candidate_axes": [
    {
      "x_axis": "SMB Fit (simplicity / ease of adoption)",
      "y_axis": "Price accessibility (lower cost = higher score)",
      "rationale": "Directly maps to Tessivane's stated differentiation. ServiceTitan scores low on both (complex, expensive); Jobber and Housecall Pro sit in the middle; Tessivane claims the high-SMB-fit, high-affordability position. This axis pair reveals the core trade-off buyers face."
    },
    {
      "x_axis": "Feature breadth (scheduling-only to full FSM platform)",
      "y_axis": "Time to first value (speed of onboarding)",
      "rationale": "Differentiates on the implementation experience. Enterprise platforms offer more features but take longer to deploy; lighter tools go live faster. Tessivane as a seed-stage product likely favors speed over breadth, which is meaningful for SMB buyers."
    },
    {
      "x_axis": "Target business size (micro-SMB to enterprise)",
      "y_axis": "Dispatch automation depth",
      "rationale": "Shows how well each platform handles the core dispatch job vs. who it targets. ServiceTitan is built for scale; manual is built for nobody in particular; Tessivane and peers compete in the SMB zone."
    }
  ],
  "metadata": {"run_id": "cw-cp-smoke-0a1b2c3d"}
}
ENDJSON
